use WebCommander\Resources\Cities\Cities;

$response = Cities::listCities($client, ['country' => 'AU', 'state' => 'VIC', 'limit' => 20]);

foreach ($response->map['cities'] as $city) {
    echo $city['id'], ' ', $city['name'], ' ', $city['post_code'], ' ', $city['state']['code'], ' ', $city['country']['code'], PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;
